INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('74a474ef-4336-4001-a941-a14e740938a2', '21feff02-016d-46e2-bb9d-c27495133b1b', '80. óra: Létraverseny I.', 'Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "9684ec7d-735b-4813-84ef-1f84ff63e9f6", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "b1c2b3d9-8307-487e-b425-da8eba50153e", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "a51967f8-b999-4651-8607-14fdd81c20aa", "text": "1 : 3", "isCorrect": true}, {"id": "9db6d933-2507-409f-b3fb-c713085581f6", "text": "1 : 5", "isCorrect": false}, {"id": "32610752-d826-46d3-8be2-d71806f41efb", "text": "3 : 1", "isCorrect": false}, {"id": "a8ebe091-b8d0-4c05-b398-42f0c1d5999d", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "e83d262f-5b20-4da7-acb6-4f166fe275c7", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "1ed2b2d6-e7a4-4fd0-ad31-08e0055847c0", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "20a56182-76bd-4df1-9e43-5ebda6c41bac", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "1cfc34b5-84d7-4e84-8452-94287297254c", "text": "Igaz", "isCorrect": true}, {"id": "46a5a17c-e320-47ac-8db8-3fc2ca026bbb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ccd51087-84f1-4e82-b903-1cf6e4a35c13", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "02b0de11-5434-41fc-9f88-22aaaeb29da1", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "5296e340-dbf3-450c-ac05-8f13d5cadf7f", "text": "Igaz", "isCorrect": true}, {"id": "c2751717-a063-4e1d-abdc-c107bf8c8af5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2b2c953e-9a22-4a21-89b4-972da38c1398', '21feff02-016d-46e2-bb9d-c27495133b1b', '81. óra: Százalékszámítás', '1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8495838a-e963-4f8a-842a-858d4f69d066", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "c12f55bb-5c2e-4c18-9e47-2bdd5104fea3", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "12404573-1aea-4eb0-b722-3e9b59e9c990", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "b72851b3-e498-43ac-943e-75657f6660f9", "text": "100 egészet", "isCorrect": false}, {"id": "bff22726-9f73-4490-a7cb-5eac51ce0a3b", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "d278b238-b98e-412e-a418-70b21ff7fe8f", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "4425f022-a14f-4d68-8a16-d1cdb8c884d2", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "20fa9c40-b2db-47e3-972e-c2f3be728759", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "3233f126-2683-4e11-b5a9-23a6b2bee40e", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "ba1f139d-41bd-44d6-97ed-3230e9f8763a", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "69631cb4-bf33-400a-a586-4ec8bcf10a5c", "text": "Igaz", "isCorrect": true}, {"id": "558d1aac-e6ab-4dcb-881d-826d9f6c54e0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f457fd48-3851-4515-85cc-d66d81f75d3a", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "c15186dd-88b5-4338-b16a-c74705f5ead3", "text": "Igaz", "isCorrect": true}, {"id": "177a2b1a-6c88-4e4e-83f7-a8a57acd2f27", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e7148976-7c2d-4612-9932-c12e20a94bfa', '21feff02-016d-46e2-bb9d-c27495133b1b', '82. óra: A százalékszámítás gyakorlása', 'Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "e0adace2-c037-46bb-b77e-d0f1dccfe3d2", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "13f9cde2-a7fd-436c-b931-f1775d0f3295", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "cc0250b3-d4a3-4b93-b71f-48fa5000380c", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "268a3ddb-de3a-4bc7-82f0-c6a613abbfe3", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "c4493ca7-daad-4052-9be9-c882f82a8ca0", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "10996895-19a0-48d4-be6b-9e4031fabf4c", "text": "Igaz", "isCorrect": true}, {"id": "00ce588e-2461-4dad-9dad-36e5dd75fec4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "06adf7e4-f62a-428b-8e91-27847786fb00", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "6cb54c8e-4ff6-4cff-a2c9-b07745761e3d", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5c2aabc6-46d6-4600-94b0-0a27fa620f02', '21feff02-016d-46e2-bb9d-c27495133b1b', '83. óra: Feladatmegoldás', 'Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f3bde8ab-c1c1-4bc2-bb09-b2abe4783cb1", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "b94b2b47-7ae3-4a60-b374-113ddbe598c1", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "8ea53b30-1f6a-4a54-b729-e433b735c4ba", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "efe292f7-fea2-485d-8fa3-a2a12d876b43", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "1c54d32b-3279-4839-9201-a26d070f0723", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "947d7a73-1746-43ef-bd2d-0722bb28cd62", "text": "Igaz", "isCorrect": true}, {"id": "9cdeb4af-9cbb-4151-a19f-b38fbd844778", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1b2eed08-f72e-4ab7-b136-c373bc46aae8", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "00cdc390-52f5-43ce-81ea-f653a17748a5", "text": "Igaz", "isCorrect": true}, {"id": "969dd899-7f4c-4a07-9c1e-c40d49b4c547", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e38eabe9-f1f8-47eb-bac0-d47cb94b005a", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('386608bc-bfbf-40d0-911d-78f247245863', '21feff02-016d-46e2-bb9d-c27495133b1b', '84. óra: Feladatmegoldás II.', 'Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "1a76baa9-6073-41d4-8cdc-d296c56aea0e", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "6397be20-0ffd-4b36-9d16-699c6e29284f", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "2d59780c-1a8f-47e9-8b12-b76ec2ed81ab", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "529a9757-9c3d-4978-85a0-566c73029dec", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "f32711de-7230-4566-a093-6049b5274633", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "bf076d85-c7db-4f93-a446-b416bccb8830", "text": "Igaz", "isCorrect": false}, {"id": "4151e981-103a-464b-b78e-8d7eb39da7eb", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "75cdc09a-76cc-46f6-afc8-750ce93fa623", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "95a9583f-285f-489b-a787-40289a141d1f", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "2e5cd6b0-cc56-43d5-bfd1-9e30a3211e5e", "text": "Igaz", "isCorrect": true}, {"id": "c1150de9-7eeb-4db0-8188-da26843bc9d7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3fc8175e-b713-48de-8c20-df5bc28ac954', '21feff02-016d-46e2-bb9d-c27495133b1b', '85. óra: Projektóra', 'Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "1049180e-f539-4607-a253-386d76b0ae48", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "725131c8-243d-4592-9d39-5b9b39859c80", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "34a46004-3461-473f-a4a4-63453911dcd0", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "e7ad7513-23f3-469b-b22c-1084b32ceab5", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "b355e1c1-a13b-4231-9d42-b8a4aa8ec137", "text": "Igaz", "isCorrect": true}, {"id": "909dedf4-2839-4e69-823b-86cc8384b80d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c67f9026-7ea3-460c-9271-357c6e9cce8b", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "dfaa1abf-4cbf-4ca0-a5e6-a07a52d214bd", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "0e98b55b-716a-4833-8576-ba1f74b69058", "text": "Igaz", "isCorrect": true}, {"id": "f87b7ea6-527e-4c03-b92c-568059214689", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4e58e6f1-cb64-4968-8b94-d0e98c2f1809", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "59442ff9-3653-46e0-8eff-a6f98e0d9765", "text": "Igaz", "isCorrect": true}, {"id": "31ad9bea-1584-4c11-abdc-3297d410cc7d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ea39b05b-3c5b-4752-8ff1-a281e50f5ce6', '21feff02-016d-46e2-bb9d-c27495133b1b', '86. óra: Nyitott mondatok', 'Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "6411b6dd-3389-47cf-adbd-1cca89f763ff", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "da7cdb40-8466-4e7a-9ed1-05238331dd0c", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "42fbc8a2-5912-4170-9cd0-559d298e279e", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "4bfc627b-9ffa-4965-8c6a-ac7f7b8efce0", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "c98d38d5-364f-48e3-a09c-c933cbbe8e29", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "c335b0cf-ffd8-44a2-b16c-80a397a43fc4", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "611aa2e4-4a59-4ec0-b557-eb8b977f91b2", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "519ebad6-2ba2-4f7c-a74c-6839d8d6aab5", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "46d8fe90-eb11-4334-872e-63ea20ded154", "text": "Igaz", "isCorrect": true}, {"id": "fad93dba-1c24-4b0a-bbaa-ee4a0557338c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cd948bc6-354e-4484-949f-7d574b515cb8", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "28b9da77-4cfb-46d4-bb1b-1edfdf23522d", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "296f3b87-a9f9-4d66-a8c5-8eeff65409b5", "text": "Igaz", "isCorrect": true}, {"id": "8bcf787a-1a1c-45a9-9632-6f0d0fcef6cf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7915c3ba-d05d-471a-8ab7-5cac5fda724e", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('be5975ce-9b02-4743-85ce-5b6161536ae9', '21feff02-016d-46e2-bb9d-c27495133b1b', '87. óra: Feladatmegoldás: Nyitott mondatok', 'Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "659290ff-a3cc-4cc1-9df2-ea8f360b186f", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "3fb859eb-2c0a-4503-afb5-98077da11ccd", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "cb8cca6e-6903-4c2d-afa9-f23a86b34ee9", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "b650c67b-f32d-4cbd-aeda-1ba043bb472e", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "b833a072-b4c6-4854-bd2a-3bc479dc41d0", "text": "Igaz", "isCorrect": true}, {"id": "f7b05d02-cc46-41d9-be37-fabe72f5eb0a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8461354d-aae8-4d3e-bc65-1fa078c87ccc", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "b6506ae5-b628-4652-8c7a-e2f8c86b34cd", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "b60fb3e4-2665-4e3d-95ec-e3c9b247dfc5", "text": "Igaz", "isCorrect": true}, {"id": "64a29557-2353-4260-b9bf-5847e8435e7b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d2dcd4c4-4224-4d1b-a320-9d37797cf49f", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('61871784-1146-4d24-8585-7b49431a818a', '21feff02-016d-46e2-bb9d-c27495133b1b', '88. óra: Gyakorlóóra', 'Nyitott mondatok és műveleti sorrend gyakorlása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f6bc3f31-ff20-43df-8b19-be3956fc1e86", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "c04e03c2-a144-4fa7-af80-44ea87b2dbe7", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "56c3e32e-7ea8-46a2-96a3-c02cbee3e12d", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "ce61808b-1639-4535-af67-750bc2f0e726", "text": "Igaz", "isCorrect": true}, {"id": "07b76023-34fe-4192-8bfb-f51e119f0e6e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "436aa320-4509-45d0-956a-c604f027a581", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "634be62f-94e6-4c3a-b4e5-64138bc1519e", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "922759a2-8bbf-4b4a-9353-e6c0761583bb", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "acb0721b-a709-46d8-be3e-26901a1fc00a", "text": "Igaz", "isCorrect": true}, {"id": "f3e4956e-b6aa-4af0-9b50-1554c0da36e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bc1d30b8-898c-48ea-9a9d-0c23749d8c62", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('37bff0b6-1d57-4e35-9e09-328025483fdd', '21feff02-016d-46e2-bb9d-c27495133b1b', '89. óra: Szöveges feladatok', 'Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "454701fc-03ef-45f3-93aa-b1669283b1c7", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "20cc9c64-23e3-428b-92bb-70416855175c", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "5e738e7d-be05-4e7c-9fb8-3359a07e24c6", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "429d6bb0-abe0-497f-aae4-51c435ca0380", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "77420544-7ff3-4f6f-82c7-ef5c16cd5a22", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "a59bd6ab-4db2-4376-b1a7-5b164c001157", "text": "Igaz", "isCorrect": true}, {"id": "4833341b-eb98-450e-b9ec-a5bd9762bf76", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56dd61cf-7c8e-4a5c-a45b-c9ce8da28237", "text": "Ha a feladatban a ''kétszer annyi'' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "8eb7c10b-7379-40b8-8dd1-41ed9c9260a2", "text": "Igaz", "isCorrect": true}, {"id": "7a8cba4f-4ca6-4deb-92a4-b6dcd489e12d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "33add50c-ad96-4667-9aa0-7537906ae64d", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW());